  "lapaz-sajama":{"t":"4 h 30","how":"Bus vers Arica (Chili), descendre au croisement de Sajama, puis taxi. Plus simple en voiture ou en tour.","road":"Ruta 1 jusqu'à Patacamaya, puis Ruta 4 vers Tambo Quemado."},
  "lapaz-rurrenabaque-avion":{"t":"40 à 50 min de vol","how":"Vols BoA et EcoJet (petits avions, souvent complets : réserver).","note":"Vol spectaculaire au-dessus des Andes."},
  "coroico-rurrenabaque":{"t":"10 à 13 h","how":"Bus La Paz – Rurrenabaque qui passent par Yolosa.","road":"Ruta 3 : Caranavi → Palos Blancos → Yucumo, puis Ruta 8 jusqu'à Rurrenabaque. Route améliorée, mais longue."},
  "lapaz-rurrenabaque":{"t":"12 à 15 h","how":"Bus de nuit depuis la Terminal Minasa (Villa Fátima).","road":"Ruta 3 (route des Yungas) → Caranavi → Yucumo, puis Ruta 8 jusqu'à Rurrenabaque."},
  "rurrenabaque-madidi":{"t":"3 à 5 h en pirogue","how":"Inclus dans le tour (agence ou lodge communautaire)."},
  "rurrenabaque-pampas":{"t":"3 h de 4x4 + bateau","how":"Inclus dans le tour des pampas."},
  "rurrenabaque-trinidad":{"t":"10 à 14 h","how":"Bus via San Borja, route en partie en terre (difficile en saison des pluies).","road":"Ruta 8 jusqu'à Yucumo, puis Ruta 3 : San Borja → San Ignacio de Moxos → Trinidad."},
  "lapaz-trinidad-avion":{"t":"1 h de vol","how":"Vols BoA."},
  "oruro-lapaz":{"t":"3 h 30 à 4 h","how":"Bus toutes les 30 min.","road":"Ruta 1, double voie : Oruro → Caracollo → Patacamaya → El Alto."},
  "oruro-sajama":{"t":"4 h","how":"Voiture ou tour (peu de bus).","road":"Routes de l'Altiplano vers l'ouest (Ruta 12 et Ruta 27, par Curahuara de Carangas), puis Ruta 4 vers Sajama."},
  "oruro-uyuni-train":{"t":"7 h","how":"Trains FCA : Expreso del Sur et Wara Wara del Sur, quelques départs par semaine seulement (vérifier les horaires sur fca.com.bo).","note":"Le plus confortable et le plus beau : flamants roses au bord du lac Poopó."},
  "oruro-uyuni":{"t":"6 à 7 h","how":"Bus depuis la Terminal d'Oruro.","road":"Ruta 1 jusqu'à Challapata, puis route asphaltée vers Uyuni (Ruta 30)."},
  "lapaz-uyuni":{"t":"9 à 11 h (de nuit)","how":"Bus de nuit touristiques (Todo Turismo, Trans Omar...) depuis la Terminal de La Paz.","road":"Ruta 1 jusqu'à Challapata, puis route asphaltée vers Uyuni."},
  "lapaz-uyuni-avion":{"t":"1 h de vol","how":"Vols BoA quotidiens ou presque.","note":"Fait gagner une nuit de bus."},
  "uyuni-salar":{"t":"Inclus dans le tour","how":"Tour en 4x4 avec chauffeur-guide et cuisinière. Réserver à Uyuni (comparer les agences) ou à l'avance."},
  "uyuni-potosi":{"t":"4 h","how":"Bus fréquents.","road":"Ruta 5, asphaltée, à travers l'Altiplano."},
  "uyuni-tupiza":{"t":"4 à 6 h","how":"Bus quotidiens.","road":"Ruta 21 vers le sud par Atocha, aujourd'hui en grande partie asphaltée."},
  "uyuni-tupiza-train":{"t":"5 h 30","how":"Même ligne FCA que depuis Oruro (prolongée jusqu'à Villazón)."},
